+  for (let i = names.length - 1; i > 0; i--) {
+    const j = Math.floor(Math.random() * (i + 1));
+    [names[i], names[j]] = [names[j], names[i]];
+  }
+  const spawns = world.botSpawns.slice();
+  for (let i = 0; i < 9; i++) {
