+  const pd = Math.hypot(bot.pos.x - player.pos.x, bot.pos.z - player.pos.z);
+  if (pd < 105) audio.shot(bot.weaponKey, pd);
+}
+
+function pickRoamPoint(bot) {
+  const angle = rand(0, Math.PI * 2);
+  const r = rand(5, Math.max(8, zone.radius * 0.82));
